def get_basedir():
    if 'STORAGE_ROOT' not in os.environ:
        raise EnvironmentError('You have to specify an STORAGE_ROOTenvironmental variable see getting_started')
    elif not os.environ['STORAGE_ROOT'].exists():
        raise FileNotFoundError(f"You have to specify an existing STORAGE_ROOTenvironmental variable see getting_started.\nGot: {os.environ['STORAGE_ROOT']}")
    basedir = (Path(os.environ['STORAGE_ROOT']) / 'acoustic_model').expanduser().resolve()
    if not basedir.is_dir():
        raise FileNotFoundError(f'No such directory: {basedir}\nrun `mkdir -p {basedir}`')
    return basedir

