def _serialize_stock(offer_id: int, stock: Optional[CollectiveStock]=None) -> dict:
    if stock:
        if FeatureToggle.ENABLE_NEW_COLLECTIVE_MODEL.is_active():
            stockId = stock.id
        else:
            stockId = stock.stockId
        return {'id': humanize(stockId), 'offerId': humanize(offer_id), 'hasBookingLimitDatetimePassed': stock.hasBookingLimitDatetimePassed, 'remainingQuantity': 1, 'beginningDatetime': stock.beginningDatetime}
